#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> g(n, vector<int>(n));

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> g[i][j];

    int S = 1 << n;

    vector<vector<int>> dp(S, vector<int>(n, INF));

    dp[1][0] = 0;

    for (int mask = 1; mask < S; mask++) {
        for (int i = 0; i < n; i++) {
            if (!(mask >> i & 1)) continue;
            if (dp[mask][i] == INF) continue;

            for (int j = 0; j < n; j++) {
                if (mask >> j & 1) continue;
                int nxt = mask | (1 << j);
                dp[nxt][j] = min(dp[nxt][j], dp[mask][i] + g[i][j]);
            }
        }
    }

    cout << dp[S - 1][n - 1];

    return 0;
}
